                              "tier": {
                                "type": "string"
                              },
                              "priceUsd": {
                                "type": "number"
                              }
                            }
                          }
                        }
                      }
                    },
                    "description": "Event-based pricing information"
                  }
                },
                "required": [
                  "model",
                  "isFree"
                ]
              },
              "stats": {
                "type": "object",
                "properties": {
                  "totalUsers": {
                    "type": "number",
