                  },
                  "monthlyUsers": {
                    "type": "number",
                    "description": "Monthly active users"
                  },
                  "successRate": {
                    "type": "number",
                    "description": "Success rate percentage"
                  },
                  "bookmarks": {
                    "type": "number",
                    "description": "Number of bookmarks"
                  }
                }
              },
              "rating": {
                "type": "object",
                "properties": {
                  "average": {
                    "type": "number",
                    "description": "Average rating"
                  },
                  "count": {
                    "type": "number",
                    "description": "Number of ratings"
                  }
                }
              },
              "modifiedAt": {
                "type": "string",
                "description": "Last modification date"
              },
              "isDeprecated": {
                "type": "boolean",
                "description": "Whether the Actor is deprecated"
              }
            },
            "required": [
              "url",
              "fullName",
              "developer",
              "description",
              "categories",
              "pricing"
            ]
          },
          "description": "List of Actor cards matching the search query"
        },
        "query": {
          "type": "string",
          "description": "The search query used"
        },
        "count": {
          "type": "number",
          "description": "Number of Actors returned"
        },
        "instructions": {
          "type": "string",
          "description": "Additional instructions for the LLM to follow when processing the search results."
        }
      },
      "required": [
        "actors",
        "query",
        "count"
      ]
    },
    "annotations": {
      "title": "Search Actors",
      "readOnlyHint": true,
      "idempotentHint": true,
      "openWorldHint": false
    }
  },
