              "type": "array",
              "items": {
                "type": "object"
              },
              "description": "Preview of first 5 dataset items"
            }
          },
          "required": [
            "datasetId",
            "itemCount",
            "schema",
            "previewItems"
          ]
        }
      },
      "required": [
        "runId",
        "status",
        "startedAt"
      ]
    },
    "annotations": {
      "title": "Get Actor run",
      "readOnlyHint": true,
      "idempotentHint": true,
      "openWorldHint": false
    }
  },
