    description: "Aktív ágensek listázása",
    enabled: true,
    category: "server",
    parameters: [],
  },
  {
    id: "agent_registry",
    name: "agent_registry",
    description: "Összes ágens definíció listázása",
    enabled: true,
    category: "server",
    parameters: [],
  },
  {
    id: "agent_delegate",
    name: "agent_delegate",
    description: "Feladat delegálása ágensnek",
    enabled: true,
    category: "server",
    parameters: [
      { name: "agent_name", type: "string", required: true },
      { name: "task", type: "string", required: true },
    ],
  },
  {
    id: "agent_execute",
    name: "agent_execute",
    description:
      "Execute an agent with optional JSON context (CLI compatibility)",
    enabled: true,
    category: "server",
    parameters: [
      { name: "agentName", type: "string", required: true },
      { name: "task", type: "string", required: true },
      { name: "context", type: "string", required: false },
    ],
  },
  {
