        type: "boolean",
        description: "Include line items in output",
        default: false,
      },
      clear_first: {
        type: "boolean",
        description: "Clear sheet before writing (if append=false)",
        default: false,
      },
      skip_duplicates: {
        type: "boolean",
        description: "Skip duplicate invoices by invoice_no (Phase 4)",
        default: true,
      },
      batch_size: {
