        default: 75,
      },
    },
    required: ["invoices"],
  },
};

/**
 * Write invoices to Google Sheets
 * Phase 4 features: duplicate detection, batch write, Phoenix Protocol retry
 */
export async function writeSheetsInvoicesHandler(params: {
  invoices: Record<string, unknown>[];
  append?: boolean;
  include_line_items?: boolean;
  clear_first?: boolean;
  skip_duplicates?: boolean;
  batch_size?: number;
}): Promise<{
  success: boolean;
  data?: Record<string, unknown>;
  error?: string;
}> {
  try {
    const {
      invoices,
      append = true,
      include_line_items = false,
      clear_first = false,
      skip_duplicates = true,
      batch_size = 75,
    } = params;

    if (!invoices || invoices.length === 0) {
      return {
        success: false,
        error: "invoices array cannot be empty",
      };
    }

    logInfo("writeSheetsInvoices", `Writing ${invoices.length} invoices to Sheets (Phase 4: skip_duplicates=${skip_duplicates}, batch_size=${batch_size})`);

    // Python subprocess (updated for Phase 4)
    const pythonCode = `import sys
sys.path.insert(0, '"'"'.'"'"')
import json
from myai.clients.google_sheets_client import GoogleSheetsClient
from myai.schemas.invoice import InvoiceData
from datetime import date

try:
    client = GoogleSheetsClient()
    
    # Deserialize invoices JSON to InvoiceData
    invoices_data = ${JSON.stringify(invoices)}
    invoice_objects = []
    
    for inv in invoices_data:
        # Convert date strings back to date objects
        if invoice_date := inv.get('invoice_date'):
            inv['invoice_date'] = invoice_date if isinstance(invoice_date, str) else str(invoice_date)
        if due_date := inv.get('due_date'):
            inv['due_date'] = due_date if isinstance(due_date, str) else str(due_date)
        
        invoice_objects.append(InvoiceData(**inv))
    
    if ${clear_first}:
        client.clear_sheet()
    
    # Phase 4: Use enhanced write_invoices with duplicate detection & batch optimization
    result = client.write_invoices(
        invoices=invoice_objects,
        append=${append},
        include_line_items=${include_line_items},
        skip_duplicates=${skip_duplicates},
        batch_size=${batch_size}
    )
    
    print(json.dumps(result))
    
except Exception as e:
    import traceback
    print(json.dumps({
        "success": False,
        "error": str(e),
        "type": type(e).__name__,
        "traceback": traceback.format_exc()
    }))
    sys.exit(1)
`;

    return new Promise((resolve) => {
      const python = spawn("python", ["-c", pythonCode]);
      let output = "";
      let error = "";

      python.stdout.on("data", (data: Buffer) => {
        output += data.toString();
      });

      python.stderr.on("data", (data: Buffer) => {
        error += data.toString();
      });

      python.on("close", (code: number) => {
        if (code !== 0) {
          logError("writeSheetsInvoices", `Python error: ${error.substring(0, 200)}`);
          resolve({
            success: false,
            error: `Python error: ${error}`,
          });
          return;
        }

        try {
          const result = JSON.parse(output);

          if (result.success) {
            const duplicatesInfo = result.duplicates_skipped > 0 
              ? ` (${result.duplicates_skipped} duplicates skipped)` 
              : "";
            logInfo("writeSheetsInvoices", `✅ ${result.row_count} invoices written${duplicatesInfo}`);
          } else {
            logError("writeSheetsInvoices", result.error);
          }

          resolve({
            success: result.success,
            data: result,
          });
        } catch {
          logError("writeSheetsInvoices", "JSON parse error");
          resolve({
            success: false,
            error: `Parse error: ${output.substring(0, 200)}`,
          });
        }
      });
    });
  } catch (e) {
    const error = e instanceof Error ? e.message : String(e);
    logError("writeSheetsInvoices", error);
    return {
      success: false,
      error,
    };
  }
}

/**
 * CometBrowserAgent - Hibrid, önjavító és memóriával rendelkező böngésző ügynök.
 * A CometOrchestrator Python modult használja a háttérben.
 *
 * @author Brunella Core Team
 * @version 1.0.0
 */

import { BaseAgent, AgentContext, AgentResult } from './BaseAgent.js';
import { logInfo, logError, setAgentStatus } from '../utils/logger.js';
import { formatResponse } from '../utils/responseFormatter.js';

export class CometBrowserAgent extends BaseAgent {
  name = 'CometBrowser';
  role = 'Comet-szintű autonóm böngésző ügynök';
  description = 'Természetes nyelvű webfeladatok (keresés, adatkinyerés, form kitöltés) önjavító logikával és memóriával.';
  capabilities = [
    'web_search',
    'data_extract',
    'form_fill',
    'self_healing',
    'selector_memory',
    'vision_analysis'
  ];

  private readonly API_URL = 'http://localhost:8000/comet/execute';

  /**
   * Feladat végrehajtása a Python hibrid motor segítségével
   */
  async executeTask(context: AgentContext): Promise<AgentResult> {
    const task = (context.task || '').trim();
    setAgentStatus(this.name, 'working', task.slice(0, 60));

    logInfo(this.name, `Comet feladat indítása: "${task}"`);

    try {
      // 1. Python FastAPI hívás
      const response = await fetch(this.API_URL, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ 
            task, 
            context: context.context || {} 
        })
      });

      if (!response.ok) {
        throw new Error(`FastAPI hiba: ${response.status} ${response.statusText}`);
      }

      const result = await response.json();
      
      logInfo(this.name, `Comet kész: success=${result.success}, próbálkozások=${result.attempts}`);

      // 2. Válasz formázása és visszaküldése
      const message = result.success 
        ? `Sikeresen végrehajtottam a böngésző feladatot (${result.attempts} próbálkozásból).`
        : `Sajnos nem sikerült befejezni a feladatot: ${result.error}`;

      return {
        success: result.success,
        message: formatResponse(result, this.name),
        data: result
      };

    } catch (error: unknown) {
      const errorMsg = error instanceof Error ? error.message : String(error);
      logError(this.name, `Végrehajtási hiba: ${errorMsg}`);
      
      return {
        success: false,
        message: `Hiba történt a Comet motorral való kommunikáció során: ${errorMsg}`,
        data: { error: errorMsg }
      };
    } finally {
      setAgentStatus(this.name, 'idle');
    }
  }
}

export default CometBrowserAgent;

