import fs from 'fs';

const inputPath = 'F:\\mcp-brunella-core\\conductor\\tracks\\trojan-horse-campaign-20260224\\fogorvosok_leads_20260224_2036.csv';
const outputPath = 'F:\\mcp-brunella-core\\conductor\\tracks\\trojan-horse-campaign-20260224\\fogorvosok_leads_CLEAN.csv';

const content = fs.readFileSync(inputPath, 'utf8');
const lines = content.split('\n');
const headers = lines[0].split(',');

// Find indices
const idxTitle = headers.indexOf('title');
const idxEmails = headers.indexOf('emails');
const idxPhone = headers.indexOf('phone');
const idxWebsite = headers.indexOf('website');
const idxScore = headers.indexOf('totalScore');
const idxAddress = headers.indexOf('address');

const cleanLines = ['Cégnév,Email,Telefon,Weboldal,Értékelés,Cím'];

for (let i = 1; i < lines.length; i++) {
    if (!lines[i].trim()) continue;

    // Simple CSV parser (handling quotes would be better, but for a quick fix this might work if columns don't have commas inside quotes)
    // Actually, the previous read_file showed some columns have JSON strings with escaped quotes.
    // Let's use a more robust regex for CSV splitting
    const parts = lines[i].match(/(".*?"|[^,]+)(?=\s*,|\s*$)/g);

    if (parts && parts.length >= headers.length) {
        const row = [
            parts[idxTitle] || '',
            parts[idxEmails] || '',
            parts[idxPhone] || '',
            parts[idxWebsite] || '',
            parts[idxScore] || '',
            parts[idxAddress] || ''
        ];
        cleanLines.push(row.join(','));
    }
}

fs.writeFileSync(outputPath, cleanLines.join('\n'));
console.log(`Cleaned CSV saved to: ${outputPath}`);

